-- Protect server-controlled progression balances from direct client edits.
revoke update on table public.users from authenticated;
grant update (display_name, current_energy_mode) on table public.users to authenticated;

-- Reward events are written by trusted game logic, not directly by clients.
revoke insert on table public.reward_events from authenticated;

-- Recreate completion RPC as a tightly-scoped privileged operation.
create or replace function public.complete_task(p_task_id uuid)
returns table (
  task_id uuid,
  xp_awarded integer,
  coins_awarded integer,
  total_xp integer,
  coin_balance integer
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_task public.tasks%rowtype;
  v_total_xp integer;
  v_coin_balance integer;
begin
  if v_uid is null then
    raise exception 'authentication required';
  end if;

  select *
    into v_task
  from public.tasks
  where id = p_task_id
    and user_id = v_uid
    and status = 'open'
  for update;

  if not found then
    raise exception 'task not found, not owned by caller, or already completed';
  end if;

  update public.tasks
  set status = 'completed',
      completed_at = now()
  where id = p_task_id
    and user_id = v_uid
    and status = 'open';

  insert into public.reward_events (
    user_id,
    task_id,
    event_type,
    xp_amount,
    coin_amount
  )
  values (
    v_uid,
    p_task_id,
    'task_completed',
    coalesce(v_task.xp_value, 0),
    coalesce(v_task.coin_value, 0)
  );

  update public.users
  set total_xp = coalesce(public.users.total_xp, 0) + coalesce(v_task.xp_value, 0),
      coin_balance = coalesce(public.users.coin_balance, 0) + coalesce(v_task.coin_value, 0),
      level = greatest(
        1,
        floor(
          (coalesce(public.users.total_xp, 0) + coalesce(v_task.xp_value, 0)) / 100.0
        )::int + 1
      )
  where id = v_uid
  returning public.users.total_xp, public.users.coin_balance
    into v_total_xp, v_coin_balance;

  return query
  select
    p_task_id,
    coalesce(v_task.xp_value, 0),
    coalesce(v_task.coin_value, 0),
    v_total_xp,
    v_coin_balance;
end;
$$;

revoke execute on function public.complete_task(uuid) from public, anon;
grant execute on function public.complete_task(uuid) to authenticated;

create table if not exists public.cosmetics (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name text not null,
  category text not null check (category in ('outfit','accessory','familiar','room','effect')),
  rarity text not null default 'common' check (rarity in ('common','uncommon','rare','epic','legendary')),
  description text,
  price integer not null default 0 check (price >= 0),
  premium boolean not null default false,
  asset_key text,
  active boolean not null default true,
  created_at timestamptz not null default now()
);

create table if not exists public.user_cosmetics (
  user_id uuid not null references auth.users(id) on delete cascade,
  cosmetic_id uuid not null references public.cosmetics(id) on delete cascade,
  unlocked_at timestamptz not null default now(),
  source text not null default 'shop',
  equipped boolean not null default false,
  primary key (user_id, cosmetic_id)
);

alter table public.cosmetics enable row level security;
alter table public.user_cosmetics enable row level security;

drop policy if exists "Authenticated users can view active cosmetics" on public.cosmetics;
create policy "Authenticated users can view active cosmetics"
on public.cosmetics
for select
to authenticated
using (active = true);

drop policy if exists "Users can view own cosmetics" on public.user_cosmetics;
create policy "Users can view own cosmetics"
on public.user_cosmetics
for select
to authenticated
using ((select auth.uid()) = user_id);

revoke all on table public.cosmetics from anon;
revoke insert, update, delete on table public.cosmetics from authenticated;
grant select on table public.cosmetics to authenticated;

revoke all on table public.user_cosmetics from anon;
revoke insert, update, delete on table public.user_cosmetics from authenticated;
grant select on table public.user_cosmetics to authenticated;

create or replace function public.purchase_cosmetic(p_cosmetic_id uuid)
returns table (
  cosmetic_id uuid,
  remaining_coins integer,
  already_owned boolean
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_price integer;
  v_balance integer;
  v_owned boolean;
begin
  if v_uid is null then
    raise exception 'authentication required';
  end if;

  select exists(
    select 1
    from public.user_cosmetics uc
    where uc.user_id = v_uid
      and uc.cosmetic_id = p_cosmetic_id
  ) into v_owned;

  select c.price
    into v_price
  from public.cosmetics c
  where c.id = p_cosmetic_id
    and c.active = true
  for share;

  if v_price is null then
    raise exception 'cosmetic not found';
  end if;

  select u.coin_balance
    into v_balance
  from public.users u
  where u.id = v_uid
  for update;

  if v_balance is null then
    raise exception 'profile not found';
  end if;

  if v_owned then
    return query select p_cosmetic_id, v_balance, true;
    return;
  end if;

  if v_balance < v_price then
    raise exception 'not enough coins';
  end if;

  update public.users
  set coin_balance = coin_balance - v_price
  where id = v_uid
  returning coin_balance into v_balance;

  insert into public.user_cosmetics(user_id, cosmetic_id, source)
  values (v_uid, p_cosmetic_id, 'shop');

  insert into public.reward_events(
    user_id, task_id, event_type, xp_amount, coin_amount
  )
  values (
    v_uid, null, 'cosmetic_purchase', 0, -v_price
  );

  return query select p_cosmetic_id, v_balance, false;
end;
$$;

revoke execute on function public.purchase_cosmetic(uuid) from public, anon;
grant execute on function public.purchase_cosmetic(uuid) to authenticated;

create or replace function public.equip_cosmetic(p_cosmetic_id uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_category text;
begin
  if v_uid is null then
    raise exception 'authentication required';
  end if;

  select c.category
    into v_category
  from public.user_cosmetics uc
  join public.cosmetics c on c.id = uc.cosmetic_id
  where uc.user_id = v_uid
    and uc.cosmetic_id = p_cosmetic_id;

  if v_category is null then
    raise exception 'cosmetic not owned';
  end if;

  update public.user_cosmetics uc
  set equipped = false
  from public.cosmetics c
  where uc.cosmetic_id = c.id
    and uc.user_id = v_uid
    and c.category = v_category;

  update public.user_cosmetics
  set equipped = true
  where user_id = v_uid
    and cosmetic_id = p_cosmetic_id;
end;
$$;

revoke execute on function public.equip_cosmetic(uuid) from public, anon;
grant execute on function public.equip_cosmetic(uuid) to authenticated;

