create or replace function public.create_boss_battle(
  p_title text,
  p_steps text[],
  p_reward_xp integer default 100,
  p_reward_coins integer default 50
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_boss_id uuid;
  v_step text;
  v_position integer := 0;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  if p_title is null or char_length(trim(p_title)) = 0 then
    raise exception 'Boss title is required';
  end if;

  if p_steps is null or array_length(p_steps, 1) is null or array_length(p_steps, 1) < 2 then
    raise exception 'A Boss Battle requires at least two steps';
  end if;

  insert into public.boss_battles(user_id, title, reward_xp, reward_coins)
  values (v_user_id, trim(p_title), greatest(coalesce(p_reward_xp,100),0), greatest(coalesce(p_reward_coins,50),0))
  returning id into v_boss_id;

  foreach v_step in array p_steps loop
    if v_step is not null and char_length(trim(v_step)) > 0 then
      insert into public.boss_steps(boss_id, user_id, title, position)
      values (v_boss_id, v_user_id, trim(v_step), v_position);
      v_position := v_position + 1;
    end if;
  end loop;

  if v_position < 2 then
    delete from public.boss_battles where id = v_boss_id;
    raise exception 'A Boss Battle requires at least two non-empty steps';
  end if;

  return v_boss_id;
end;
$$;

create or replace function public.complete_boss_step(p_step_id uuid)
returns table (
  boss_completed boolean,
  xp_awarded integer,
  coins_awarded integer,
  total_xp integer,
  coin_balance integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_boss_id uuid;
  v_reward_xp integer := 0;
  v_reward_coins integer := 0;
  v_remaining integer;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select boss_id into v_boss_id
  from public.boss_steps
  where id = p_step_id and user_id = v_user_id
  for update;

  if v_boss_id is null then
    raise exception 'Boss step not found';
  end if;

  update public.boss_steps
  set completed = true, completed_at = now()
  where id = p_step_id
    and user_id = v_user_id
    and completed = false;

  select count(*) into v_remaining
  from public.boss_steps
  where boss_id = v_boss_id
    and user_id = v_user_id
    and completed = false;

  if v_remaining = 0 then
    update public.boss_battles
    set status = 'completed', completed_at = now()
    where id = v_boss_id
      and user_id = v_user_id
      and status = 'open'
    returning reward_xp, reward_coins
    into v_reward_xp, v_reward_coins;

    if found then
      insert into public.reward_events(user_id, task_id, event_type, xp_amount, coin_amount)
      values (v_user_id, null, 'boss_battle_completed', v_reward_xp, v_reward_coins);

      update public.users
      set total_xp = total_xp + v_reward_xp,
          coin_balance = coin_balance + v_reward_coins,
          level = ((total_xp + v_reward_xp) / 100) + 1
      where id = v_user_id;
    end if;
  end if;

  return query
  select
    (select status = 'completed' from public.boss_battles where id = v_boss_id),
    v_reward_xp,
    v_reward_coins,
    u.total_xp,
    u.coin_balance
  from public.users u
  where u.id = v_user_id;
end;
$$;

revoke all on function public.create_boss_battle(text,text[],integer,integer) from public;
revoke all on function public.complete_boss_step(uuid) from public;
grant execute on function public.create_boss_battle(text,text[],integer,integer) to authenticated;
grant execute on function public.complete_boss_step(uuid) to authenticated;

