create or replace function public.complete_boss_step(p_step_id uuid)
returns table(
  boss_completed boolean,
  xp_awarded integer,
  coins_awarded integer,
  total_xp integer,
  coin_balance integer
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_id uuid := auth.uid();
  v_boss_id uuid;
  v_step_completed boolean;
  v_reward_xp integer := 0;
  v_reward_coins integer := 0;
  v_remaining integer;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select boss_id, completed
    into v_boss_id, v_step_completed
  from public.boss_steps
  where id = p_step_id
    and user_id = v_user_id
  for update;

  if v_boss_id is null then
    raise exception 'Boss step not found';
  end if;

  if v_step_completed then
    raise exception 'Boss step already completed';
  end if;

  update public.boss_steps
  set completed = true,
      completed_at = now()
  where id = p_step_id
    and user_id = v_user_id
    and completed = false;

  select count(*)
    into v_remaining
  from public.boss_steps
  where boss_id = v_boss_id
    and user_id = v_user_id
    and completed = false;

  if v_remaining = 0 then
    update public.boss_battles
    set status = 'completed',
        completed_at = now()
    where id = v_boss_id
      and user_id = v_user_id
      and status = 'open'
    returning reward_xp, reward_coins
      into v_reward_xp, v_reward_coins;

    if found then
      insert into public.reward_events(
        user_id,
        task_id,
        event_type,
        xp_amount,
        coin_amount
      )
      values (
        v_user_id,
        null,
        'boss_battle_completed',
        v_reward_xp,
        v_reward_coins
      );

      update public.users
      set total_xp = total_xp + v_reward_xp,
          coin_balance = coin_balance + v_reward_coins,
          level = ((total_xp + v_reward_xp) / 100) + 1
      where id = v_user_id;
    end if;
  end if;

  return query
  select
    (select status = 'completed'
       from public.boss_battles
      where id = v_boss_id),
    v_reward_xp,
    v_reward_coins,
    u.total_xp,
    u.coin_balance
  from public.users u
  where u.id = v_user_id;
end;
$$;

